     1|/**
     2| * IVX Senior-Developer Answer Format
     3| *
     4| * Renders the senior-developer runtime proof into the OWNER-REQUIRED strict
     5| * execution format. The owner explicitly rejected narrative prose
     6| * ("TASK UNDERSTOOD / FILES INSPECTED / ...") and the old 8-section layout.
     7| *
     8| * Every development task must return ONLY the 6 evidence sections:
     9| *
    10| *   TASK ID
    11| *   STATUS
    12| *   FILES CHANGED
    13| *   COMMANDS
    14| *   TESTS
    15| *   DEPLOYED PROOF
    16| *
    17| * Hard enforcement (no claims without real commands):
    18| *   - No files changed      -> "NO CODE CHANGED — no development was completed."
    19| *   - No tests run          -> "NOT VERIFIED — tests were not run."
    20| *   - Patch could not write -> "BLOCKED — I do not have code write access."
    21| *
    22| * CRITICAL: the user's goal text is NEVER echoed into the answer. Copying the
    23| * goal into the response caused the Fake Execution Guard to false-positive on
    24| * innocent words like "complete" ("complete the loading on this chat") and
    25| * replace a real DEPLOYED answer with a generic BLOCKED message.
    26| *
    27| * This module is runtime-free and deterministic (no network/filesystem/AI) so it
    28| * is fully unit-testable.
    29| */
    30|import type { IVXSeniorDeveloperRunProof } from './ivx-senior-developer-runtime';
    31|import type { IVXOwnerExecutionDecision } from './ivx-owner-execution-mode';
    32|import type { IVXWorkerJob, IVXWorkerJobResult } from './ivx-senior-developer-worker';
    33|
    34|function trimmed(value: unknown): string {
    35|  return typeof value === 'string' ? value.trim() : '';
    36|}
    37|
    38|/** Render one validation result as raw, copy-pasteable terminal output. */
    39|function rawValidationOutput(validation: IVXSeniorDeveloperRunProof['validations'][number]): string {
    40|  return [
    41|    `$ ${validation.command}`,
    42|    validation.stdoutTail ? validation.stdoutTail.trimEnd() : '',
    43|    validation.stderrTail ? validation.stderrTail.trimEnd() : '',
    44|    validation.error ? `error: ${validation.error}` : '',
    45|    `exit code: ${validation.exitCode ?? 'null'} -> ${validation.ok ? 'PASS' : 'FAIL'}`,
    46|  ]
    47|    .filter((line) => line.length > 0)
    48|    .join('\n');
    49|}
    50|
    51|export function isTypecheckCommand(command: string): boolean {
    52|  return /\b(tsc|typecheck|type-check|type\s+check)\b/i.test(command);
    53|}
    54|
    55|export function isTestCommand(command: string): boolean {
    56|  return /\btest\b/i.test(command) && !isTypecheckCommand(command);
    57|}
    58|
    59|function buildStatusLine(
    60|  proof: IVXSeniorDeveloperRunProof,
    61|  changedFiles: string[],
    62|): 'DEPLOYED' | 'UNVERIFIED' | 'LOCAL ONLY' | 'BLOCKED' {
    63|  const validations = proof.validations;
    64|  const testValidations = validations.filter((v) => isTestCommand(v.command));
    65|  const typecheckValidations = validations.filter((v) => isTypecheckCommand(v.command));
    66|  const checksRan = testValidations.length > 0 || typecheckValidations.length > 0;
    67|  const checksPassed = checksRan && validations.every((v) => v.ok);
    68|  const git = proof.gitDeployOperator;
    69|
    70|  const deployConfirmed =
    71|    git.status === 'executed' &&
    72|    (git.render.deployAttempted || git.github.commitAttempted) &&
    73|    proof.productionVerification.ok &&
    74|    proof.changedRouteVerification.ok;
    75|
    76|  if (proof.patchProposal.status === 'blocked') {
    77|    return 'BLOCKED';
    78|  }
    79|  if (deployConfirmed && checksPassed) {
    80|    return 'DEPLOYED';
    81|  }
    82|  if (deployConfirmed && !checksPassed) {
    83|    return 'UNVERIFIED';
    84|  }
    85|  if (changedFiles.length === 0) {
    86|    return 'LOCAL ONLY';
    87|  }
    88|  return 'LOCAL ONLY';
    89|}
    90|
    91|function buildFilesChangedLine(
    92|  changedFiles: string[],
    93|  patchStatus: IVXSeniorDeveloperRunProof['patchProposal']['status'],
    94|): string {
    95|  if (changedFiles.length > 0) {
    96|    return changedFiles.map((filePath) => `- ${filePath}`).join('\n');
    97|  }
    98|  if (patchStatus === 'blocked') {
    99|    return 'BLOCKED — I do not have code write access.';
   100|  }
   101|  return 'NO CODE CHANGED — no development was completed.';
   102|}
   103|
   104|function buildCommandsSection(proof: IVXSeniorDeveloperRunProof): string {
   105|  const validations = proof.validations;
   106|  const commands: string[] = [];
   107|
   108|  for (const validation of validations) {
   109|    commands.push(`- $ ${validation.command} -> exit ${validation.exitCode ?? 'null'} (${validation.ok ? 'PASS' : 'FAIL'})`);
   110|  }
   111|
   112|  const git = proof.gitDeployOperator;
   113|  if (git.github.commitAttempted) {
   114|    commands.push(
   115|      `- $ git commit/push -> ${git.github.commitSha ? `exit 0 (committed ${git.github.commitSha})` : `not completed (${git.reason})`}`,
   116|    );
   117|  }
   118|  if (git.render.deployAttempted) {
   119|    commands.push(
   120|      `- $ render deploy -> ${git.render.deployId ? `exit 0 (${git.render.deployStatus ?? 'triggered'} ${git.render.deployId})` : `not completed (${git.render.error ?? git.reason})`}`,
   121|    );
   122|  }
   123|  if (proof.productionVerification.ok) {
   124|    commands.push('- $ curl /health -> exit 0 (200 healthy)');
   125|  }
   126|
   127|  return commands.length > 0 ? commands.join('\n') : 'NONE — no commands were executed.';
   128|}
   129|
   130|function buildTestsSection(proof: IVXSeniorDeveloperRunProof): string {
   131|  const testValidations = proof.validations.filter((v) => isTestCommand(v.command));
   132|  return testValidations.length > 0
   133|    ? testValidations.map(rawValidationOutput).join('\n\n')
   134|    : 'NOT VERIFIED — tests were not run.';
   135|}
   136|
   137|function buildDeployedProofSection(proof: IVXSeniorDeveloperRunProof): string {
   138|  const changedFiles = proof.changedFiles;
   139|  const git = proof.gitDeployOperator;
   140|  const lines: string[] = [];
   141|
   142|  if (changedFiles.length > 0) {
   143|    lines.push('git diff --stat (applied patch):');
   144|    for (const filePath of changedFiles) {
   145|      const op = proof.patchProposal.operations.find((operation) => operation.path === filePath);
   146|      lines.push(` ${filePath} | ${op ? op.summary : 'modified'}`);
   147|    }
   148|    lines.push('git status --short:');
   149|    for (const filePath of changedFiles) {
   150|      lines.push(` M ${filePath}`);
   151|    }
   152|    if (git.github.commitSha) {
   153|      lines.push(`commit: ${git.github.commitSha}${git.github.branch ? ` (${git.github.branch})` : ''}`);
   154|    }
   155|    lines.push(
   156|      `production /health: ${proof.productionVerification.ok ? 'healthy' : 'not confirmed'}; changed route: ${proof.changedRouteVerification.ok ? 'live' : 'not confirmed'}`,
   157|    );
   158|  } else {
   159|    lines.push('git diff --stat: (no changes)');
   160|    lines.push('git status --short: (clean)');
   161|    if (git.render.deployAttempted && git.github.commitSha) {
   162|      lines.push(`deploy-only from commit: ${git.github.commitSha}${git.github.branch ? ` (${git.github.branch})` : ''}`);
   163|    }
   164|  }
   165|
   166|  if (git.render.deployId) {
   167|    lines.push(`deploy: ${git.render.deployId} (${git.render.deployStatus ?? 'unknown'})`);
   168|  }
   169|  lines.push(`job: ${proof.jobId}`);
   170|
   171|  return lines.join('\n');
   172|}
