   174|/**
   175| * Build the senior-developer execution answer in the owner-required 6-section
   176| * format. No goal text is echoed; only taskId, status, real files, real commands,
   177| * real tests, and real deployed proof are returned.
   178| */
   179|export function buildSeniorDeveloperExecutionAnswer(
   180|  proof: IVXSeniorDeveloperRunProof,
   181|  decision: IVXOwnerExecutionDecision,
   182|): string {
   183|  if (decision.requiresApproval) {
   184|    return [
   185|      `TASK ID:\n${proof.jobId}`,
   186|      'STATUS:\nBLOCKED',
   187|      'FILES CHANGED:\n(none — requires owner confirmation before execution)',
   188|      'COMMANDS:\nNONE — guarded action halted before repo inspection.',
   189|      'TESTS:\nNOT VERIFIED — tests were not run.',
   190|      'DEPLOYED PROOF:\nNONE — owner confirmation required.',
   191|    ].join('\n\n');
   192|  }
   193|
   194|  const changedFiles = proof.changedFiles;
   195|  const status = buildStatusLine(proof, changedFiles);
   196|
   197|  return [
   198|    `TASK ID:\n${proof.jobId}`,
   199|    `STATUS:\n${status}`,
   200|    `FILES CHANGED:\n${buildFilesChangedLine(changedFiles, proof.patchProposal.status)}`,
   201|    `COMMANDS:\n${buildCommandsSection(proof)}`,
   202|    `TESTS:\n${buildTestsSection(proof)}`,
   203|    `DEPLOYED PROOF:\n${buildDeployedProofSection(proof)}`,
   204|  ].join('\n\n');
   205|}
