   207|function buildWorkerFilesChangedLine(result: IVXWorkerJobResult): string {
   208|  if (result.changedFiles.length > 0) {
   209|    return result.changedFiles.map((filePath) => `- ${filePath}`).join('\n');
   210|  }
   211|  if (result.finalStatus === 'BLOCKED') {
   212|    return 'BLOCKED — I do not have code write access.';
   213|  }
   214|  return 'NO CODE CHANGED — no development was completed.';
