   217|function buildWorkerCommandsSection(job: IVXWorkerJob, result: IVXWorkerJobResult): string {
   218|  const commands: string[] = [];
   219|  if (result.commitCreated) {
   220|    const exit = result.commitSha ? 0 : 1;
   221|    commands.push(
   222|      `- $ git commit/push -> exit ${exit} (${result.commitSha ? `committed ${result.commitSha.slice(0, 12)}` : 'attempted (no sha)'})`,
   223|    );
   224|  }
   225|  if (result.deployId) {
   226|    const exit = result.deployStatus === 'live' ? 0 : 1;
   227|    commands.push(
   228|      `- $ render deploy -> exit ${exit} (${result.deployStatus ?? 'triggered'} ${result.deployId})`,
   229|    );
   230|  }
   231|  if (result.testsRun) {
   232|    commands.push(`- $ bun test -> exit ${result.testsPassed ? 0 : 1} (${result.testsPassed ? 'PASS' : 'FAIL'})`);
   233|  }
   234|  if (result.typecheckRun) {
   235|    const typecheckPass = result.testsPassed;
   236|    commands.push(`- $ tsc --noEmit -> exit ${typecheckPass ? 0 : 1} (${typecheckPass ? 'PASS' : 'errors'})`);
   237|  }
   238|  if (result.healthOk) {
   239|    commands.push('- $ curl /health -> exit 0 (200 healthy)');
   240|  }
   241|  if (job.status !== 'completed' && job.status !== 'failed' && job.status !== 'blocked') {
   242|    commands.push(`- $ worker phase ${job.stage} -> exit pending (stage: ${job.stage}, progress: ${job.progressPercent}%)`);
   243|  }
   244|  return commands.length > 0 ? commands.join('\n') : 'NONE — no commands were executed.';
