     4| * Final safety net for the self-developer route. The router already sends
     5| * development commands to the senior-developer runtime, and
     6| * `buildSeniorDeveloperExecutionAnswer` already renders the strict evidence
     7| * format. This module is the LAST line of defence: it inspects the answer
     8| * that is about to be returned to the owner and BLOCKS it when it is narrative-only
     9| * or makes a claim it has not proven.
    10| *
    11| * Owner-mandated answer format (6 sections):
    12| *   TASK ID
    13| *   STATUS
    14| *   FILES CHANGED
    15| *   COMMANDS
    16| *   TESTS
    17| *   DEPLOYED PROOF
    18| *
    19| * Hard rules enforced here (owner spec):
    20| *   - No narrative-only answers. The 6 section headers must be present.
    21| *   - No "reviewed/prepared/initialized/awaiting approval/development phase/
    22| *     schema planning" prose unless real proof (raw command output) is present.
    23| *   - No "verified" claim without raw command output (`$ ... exit code:`).
    24| *   - No "deployed" claim without a live endpoint / commit proof line.
    25| *   - No "done/complete" claim without a real file diff.
    26| *
    27| * Pure and deterministic (no network / filesystem / AI) so it is fully unit
    28| * testable.
    29| */
    30|
    31|/**
    32| * Sentinel embedded in a guard-blocked answer. When present (together with a
    33| * BLOCKED status and NO CODE CHANGED), the answer is a recognised compliant
    34| * terminal state: it makes no success claims, so validation must not re-trigger
    35| * on the violation reasons it quotes (which legitimately mention words like
    36| * "verified"/"deployed"). This keeps the guard idempotent.
    37| */
    38|export const DEVELOPER_EXECUTION_GUARD_MARKER = 'failed developer-execution enforcement';
    39|
    40|/** Section headers every development-task answer must contain, in order. */
    41|export const REQUIRED_DEVELOPER_SECTIONS: readonly string[] = [
    42|  'TASK ID:',
    43|  'STATUS:',
    44|  'FILES CHANGED:',
    45|  'COMMANDS:',
    46|  'TESTS:',
    47|  'DEPLOYED PROOF:',
    48|];
    49|
    50|/**
    51| * Narrative phrases the owner explicitly banned. They are only allowed when the
    52| * answer also carries real proof (raw command output), because a genuine run can
    53| * legitimately say e.g. "reviewed" alongside the evidence.
    54| *
    55| * IMPORTANT: Only phrases that indicate a promise-only / planning-only response
    56| * with no execution are banned. Phrases like "starting implementation" or
    57| * "inspecting files" are valid in-progress states and must NOT be blocked —
    58| * they are the developer worker reporting its progress. The guard runs AFTER
    59| * execution, so if the worker produced real proof alongside these phrases,
    60| * they are fine. If the worker produced ONLY these phrases with no proof,
    61| * the missing-sections check (no COMMANDS / no TESTS) already
    62| * catches that — the phrase ban is a secondary safety net.
    63| */
    64|export const BANNED_NARRATIVE_PHRASES: readonly string[] = [
    65|  'awaiting approval',
    66|  'once approved',
    67|  'architecture proposal',
    68|  'execution plan',
    69|  'implementation plan',
    70|  'development plan',
    71|  'next steps required',
    72|  'next steps:',
    73|];
