    82|/** Raw command output looks like `$ <cmd> ... exit code: N`. */
    83|export function hasRawCommandOutput(answer: string): boolean {
    84|  const text = answer ?? '';
    85|  const hasCommandLine = /^\s*\$\s+\S+/m.test(text);
    86|  const hasExitCode = /\bexit\s+code:\s*\S+/i.test(text) || /->\s*exit\s+\S+/i.test(text);
