    89|
    90|/** A positive "verified" claim (not the allowed "NOT VERIFIED — ..." line). */
    91|export function claimsVerified(answer: string): boolean {
    92|  const text = (answer ?? '').toLowerCase();
    93|  // Strip the explicit honest negatives so they never count as a claim.
    94|  const stripped = text
