    99|}
   100|
   101|/** A "deployed/live in production" claim. */
   102|export function claimsDeployed(answer: string): boolean {
   103|  const text = (answer ?? '').toLowerCase();
   104|  const stripped = text
   105|    .replace(/local\s+only/g, '')
   106|    .replace(/not\s+deployed/g, '')
   107|    .replace(/deploy\s+attempted/g, '');
