   109|    || /\bdeployed\s+to\s+(?:prod|production|live|render)\b/.test(stripped)
   110|    || /\blive\s+in\s+production\b/.test(stripped);
   111|}
   112|
   113|/** A "done/complete/finished" success claim. */
   114|export function claimsDone(answer: string): boolean {
   115|  const text = (answer ?? '').toLowerCase();
   116|  const stripped = text.replace(/no\s+development\s+was\s+completed/g, '');
   117|  return /\b(?:task\s+)?(?:done|completed|complete|finished|shipped)\b/.test(stripped);
   118|}
   119|
   120|/** True when the answer proves a real file diff (changed paths in PROOF). */
   121|export function hasFileDiffProof(answer: string): boolean {
   122|  const text = answer ?? '';
   123|  if (/NO CODE CHANGED/.test(text)) {
   124|    return false;
   125|  }
