   141|/**
   142| * Validate that a candidate answer is a real developer-execution response and not
   143| * narrative-only or an unproven claim.
   144| */
   145|export function validateDeveloperExecutionAnswer(answer: string): DeveloperExecutionGuardResult {
   146|  const text = answer ?? '';
   147|
   148|  // A guard-blocked answer is a recognised compliant terminal state. It carries
   149|  // the sentinel marker, a BLOCKED status, and NO CODE CHANGED — it makes no
   150|  // success claims, so it passes without re-triggering on the violation reasons
   151|  // it quotes. This guarantees enforcement is idempotent.
   152|  if (text.includes(DEVELOPER_EXECUTION_GUARD_MARKER) && /STATUS:\s*\n?\s*BLOCKED/.test(text) && text.includes('NO CODE CHANGED')) {
   153|    return { ok: true, violations: [], hasAllSections: true, hasRawCommandOutput: false };
   154|  }
   155|
   156|  const violations: string[] = [];
   157|
   158|  const missingSections = REQUIRED_DEVELOPER_SECTIONS.filter((header) => !text.includes(header));
   159|  const hasAllSections = missingSections.length === 0;
   160|  if (!hasAllSections) {
   161|    violations.push(`missing required sections: ${missingSections.join(', ')}`);
   162|  }
   163|
   164|  const rawOutput = hasRawCommandOutput(text);
   165|
   166|  // Banned narrative phrases are only tolerated when real proof accompanies them.
   167|  if (!rawOutput) {
   168|    const lower = text.toLowerCase();
   169|    for (const phrase of BANNED_NARRATIVE_PHRASES) {
   170|      if (lower.includes(phrase)) {
   171|        violations.push(`narrative phrase without proof: "${phrase}"`);
   172|      }
   173|    }
   174|  }
   175|
   176|  if (claimsVerified(text) && !rawOutput) {
   177|    violations.push('claims "verified" without raw command output');
   178|  }
   179|
   180|  if (claimsDeployed(text) && !hasDeploymentProof(text)) {
   181|    violations.push('claims "deployed" without live endpoint / commit proof');
   182|  }
   183|
   184|  if (claimsDone(text) && !hasFileDiffProof(text)) {
   185|    violations.push('claims "done/complete" without a real file diff');
   186|  }
   187|
   188|  return {
   189|    ok: violations.length === 0,
   190|    violations,
   191|    hasAllSections,
   192|    hasRawCommandOutput: rawOutput,
   193|  };
