   204|    `TASK ID:\n(blocked)`,
   205|    'STATUS:\nBLOCKED',
   206|    'FILES CHANGED:\nNO CODE CHANGED — no development was completed.',
   207|    'COMMANDS:\nNONE — no commands were executed.',
   208|    'TESTS:\nNOT VERIFIED — tests were not run.',
   209|    `DEPLOYED PROOF:\nBLOCKED — the generated answer ${DEVELOPER_EXECUTION_GUARD_MARKER}:\n${reasons}`,
   210|  ].join('\n\n');
   211|}
