export function renderValidatorVerdict(verdict: IVXValidationVerdict): string {
  switch (verdict) {
    case 'VERIFIED':
      return 'VERIFIED';
    case 'DEPLOYED_ONLY':
      return 'DEPLOYED_ONLY — redeployed unchanged code; the requested fix was NOT implemented';
    case 'NO_CHANGE_REQUIRED':
      return 'NO_CHANGE_REQUIRED — no code change was needed or no work was completed';
    case 'BLOCKED':
      return 'BLOCKED';
    case 'FAILED':
      return 'FAILED';
    case 'NOT_COMPLETED':
    default:
      return 'NOT_COMPLETED';
  }
}

