     1|/**
     2| * IVX Completion Validator
     3| *
     4| * Final, deterministic gate before IVX can claim a task is COMPLETE, VERIFIED,
     5| * or DEPLOYED. It compares the owner-requested outcome against the actual
     6| * evidence captured during execution. This prevents the false-completion
     7| * pattern where a deploy-only redeploy or a health check is reported as a
     8| * fixed defect.
     9| *
    10| * Rules (owner mandate 2026-07-20):
    11| *   - DEPLOYED means a deployment occurred; it does NOT mean a defect is fixed.
    12| *   - VERIFIED means the requested acceptance tests passed.
    13| *   - A CODE_FIX/UI_FIX/FEATURE task cannot be VERIFIED when no code changed
    14| *     unless the root cause was genuinely external (config/data/infra).
    15| *   - If no work was completed, status must be NO_CHANGE_REQUIRED, BLOCKED,
    16| *     or FAILED — never "DEPLOYED" or "COMPLETE".
    17| *   - Never display "development completed" when the code diff is empty.
    18| */
    19|import type { IVXWorkerJobResult } from './ivx-senior-developer-worker';
    20|
    21|export const IVX_COMPLETION_VALIDATOR_MARKER = 'ivx-completion-validator-2026-07-20';
    22|
    23|export type IVXTaskType =
    24|  | 'CODE_FIX'
    25|  | 'FEATURE'
    26|  | 'UI_FIX'
    27|  | 'DATA_FIX'
    28|  | 'CONFIGURATION_FIX'
    29|  | 'INFRASTRUCTURE_FIX'
    30|  | 'DEPLOYMENT'
    31|  | 'QA_ONLY'
    32|  | 'INVESTIGATION'
    33|  | 'CONTENT_REQUEST'
    34|  | 'BUSINESS_ANALYSIS';
    35|
    36|export type IVXTaskState =
    37|  | 'RECEIVED'
    38|  | 'ANALYZING'
    39|  | 'REPRODUCING'
    40|  | 'ROOT_CAUSE_IDENTIFIED'
    41|  | 'IMPLEMENTING'
    42|  | 'CODE_CHANGED'
    43|  | 'TESTING'
    44|  | 'QA_REQUIRED'
    45|  | 'QA_IN_PROGRESS'
    46|  | 'READY_TO_DEPLOY'
    47|  | 'DEPLOYING'
    48|  | 'DEPLOYED'
    49|  | 'PRODUCTION_VERIFYING'
    50|  | 'VERIFIED'
    51|  | 'BLOCKED'
    52|  | 'FAILED'
    53|  | 'NO_CHANGE_REQUIRED';
    54|
    55|export type IVXValidationVerdict =
    56|  | 'VERIFIED'
    57|  | 'DEPLOYED_ONLY'
    58|  | 'NO_CHANGE_REQUIRED'
    59|  | 'BLOCKED'
    60|  | 'FAILED'
    61|  | 'NOT_COMPLETED';
    62|
    63|export type IVXCompletionEvidence = {
    64|  taskType: IVXTaskType;
    65|  requestedOutcome: string;
    66|  acceptanceCriteria: string[];
    67|  state: IVXTaskState;
    68|  previousVerdict: string | null;
    69|  filesChanged: string[];
    70|  testsPassed: boolean;
    71|  testsRun: boolean;
    72|  typecheckPassed: boolean;
    73|  typecheckRun: boolean;
    74|  buildPassed: boolean;
    75|  buildRun: boolean;
    76|  commitSha: string | null;
    77|  deployId: string | null;
    78|  productionHealthOk: boolean;
    79|  commitMatch: boolean;
    80|  featureVerificationOk: boolean | null;
    81|  error: string | null;
    82|  startedAt: string | null;
    83|  completedAt: string | null;
    84|  verifiedAt: string | null;
    85|};
    86|
    87|export type IVXCompletionValidationResult = {
    88|  ok: boolean;
    89|  verdict: IVXValidationVerdict;
    90|  state: IVXTaskState;
    91|  reasons: string[];
    92|  evidence: IVXCompletionEvidence;
    93|  marker: typeof IVX_COMPLETION_VALIDATOR_MARKER;
    94|};
    95|
    96|const DEVELOPMENT_TASK_TYPES: ReadonlySet<IVXTaskType> = new Set([
    97|  'CODE_FIX',
    98|  'FEATURE',
    99|  'UI_FIX',
   100|  'DATA_FIX',
   101|]);
   102|
   103|const DEPLOYMENT_TASK_TYPES: ReadonlySet<IVXTaskType> = new Set([
   104|  'DEPLOYMENT',
   105|  'INFRASTRUCTURE_FIX',
   106|  'CONFIGURATION_FIX',
   107|]);
   108|
   109|export function classifyTaskType(goal: string): IVXTaskType {
   110|  const normalized = (goal ?? '').toLowerCase();
   111|  if (/(audit|inspect|investigate|trace|root cause|diagnose|find why|report)/i.test(normalized)
   112|      && !/(fix|deploy|change|edit|apply|implement|patch|build|upgrade|create)/i.test(normalized)) {
   113|    return 'INVESTIGATION';
   114|  }
   115|  if (/\b(deploy|redeploy|push live|release|rollout|render deploy)\b/i.test(normalized)
   116|      && !/(fix|bug|patch|feature|implement|ui|scroll|loading|chat|screen)/i.test(normalized)) {
   117|    return 'DEPLOYMENT';
   118|  }
   119|  if (/(qa|test|verify|acceptance|regression|check|validate|measure)/i.test(normalized)
   120|      && !/(fix|deploy|change|edit|apply|implement|patch|build|upgrade)/i.test(normalized)) {
   121|    return 'QA_ONLY';
   122|  }
   123|  if (/(configuration|config|env|environment variable|render env|setting|toggle)/i.test(normalized)) {
   124|    return 'CONFIGURATION_FIX';
   125|  }
   126|  if (/(infrastructure|server|database|redis|queue|render service|supabase project|migrate schema)/i.test(normalized)) {
   127|    return 'INFRASTRUCTURE_FIX';
   128|  }
   129|  if (/(data fix|clean data|delete test|fix data|sanitize data|merge records|deduplicate)/i.test(normalized)) {
   130|    return 'DATA_FIX';
   131|  }
   132|  if (/(content|copy|text|wording|label|title|placeholder|typo|document|pdf|attachment)/i.test(normalized)) {
   133|    return 'CONTENT_REQUEST';
   134|  }
   135|  if (/(business model|pricing|roi|investor|deal structure|capital|workflow|process|kpi|metric)/i.test(normalized)) {
   136|    return 'BUSINESS_ANALYSIS';
   137|  }
   138|  if (/(ui|interface|screen|component|button|modal|scroll|loading|keyboard|composer|chat|flatlist|scrollview|view|color|theme|style|layout|icon|animation)/i.test(normalized)) {
   139|    return 'UI_FIX';
   140|  }
   141|  if (/(fix|bug|repair|correct|resolve|patch|issue|error|crash|exception|broken|not working|failed|slow|timeout|stuck|hang|leak|race|deadlock)/i.test(normalized)) {
   142|    return 'CODE_FIX';
   143|  }
   144|  if (/(feature|implement|add|build|create|introduce|support|enable|new capability|new module|new app|new screen)/i.test(normalized)) {
   145|    return 'FEATURE';
   146|  }
   147|  return 'INVESTIGATION';
   148|}
   149|
   150|export function computeTaskStateFromResult(result: IVXWorkerJobResult): IVXTaskState {
   151|  if (result.finalStatus === 'BLOCKED') return 'BLOCKED';
   152|  if (result.finalStatus === 'FAILED') return 'FAILED';
   153|  if (result.endToEndProductionComplete && result.commitMatch && result.healthOk) {
   154|    if (result.changedFiles.length === 0) {
   155|      return 'DEPLOYED';
   156|    }
   157|    return 'VERIFIED';
   158|  }
   159|  if (result.changedFiles.length > 0 && !result.endToEndProductionComplete) return 'CODE_CHANGED';
   160|  if (result.commitSha && result.deployId && !result.commitMatch) return 'PRODUCTION_VERIFYING';
   161|  if (result.commitSha && !result.deployId) return 'READY_TO_DEPLOY';
   162|  if (result.deployId && !result.commitMatch) return 'DEPLOYING';
   163|  return 'NO_CHANGE_REQUIRED';
   164|}
   165|
   166|export function validateCompletion(
   167|  evidence: IVXCompletionEvidence,
   168|): IVXCompletionValidationResult {
   169|  const reasons: string[] = [];
   170|
   171|  // Common evidence checks
   172|  if (evidence.previousVerdict === 'VERIFIED' && !evidence.featureVerificationOk) {
   173|    reasons.push('Previous VERIFIED claim has no feature-verification evidence');
   174|  }
   175|  if (evidence.verifiedAt && evidence.completedAt && evidence.verifiedAt < evidence.completedAt) {
   176|    reasons.push('Verification timestamp predates task completion');
   177|  }
   178|
   179|  const isDevelopment = DEVELOPMENT_TASK_TYPES.has(evidence.taskType);
   180|  const isDeployment = DEPLOYMENT_TASK_TYPES.has(evidence.taskType);
   181|
   182|  // A development task with no code change cannot be VERIFIED or DEPLOYED as a fix.
   183|  if (isDevelopment && evidence.filesChanged.length === 0) {
   184|    if (evidence.deployId && evidence.productionHealthOk && evidence.commitMatch) {
   185|      reasons.push('Development task requested but no code changed; redeploy is not a fix');
   186|      return {
   187|        ok: false,
   188|        verdict: 'DEPLOYED_ONLY',
   189|        state: 'DEPLOYED',
   190|        reasons,
   191|        evidence,
   192|        marker: IVX_COMPLETION_VALIDATOR_MARKER,
   193|      };
   194|    }
   195|    reasons.push('Development task requested but no code changed and no deployment proof');
   196|    return {
   197|      ok: false,
   198|      verdict: 'NOT_COMPLETED',
   199|      state: 'NO_CHANGE_REQUIRED',
   200|      reasons,
   201|      evidence,
   202|      marker: IVX_COMPLETION_VALIDATOR_MARKER,
   203|    };
